#ifndef PAINT_FONT_H
#define PAINT_FONT_H


// MacPaint drew its tool icons, cursors and check mark as characters of a
// private bitmap font, PaintFont. PaintFont.cpp holds those glyphs,
// generated by tools/extract_macpaint_art.py.
//
// Glyphs hang below the pen position (the font's ascent is 0), so a glyph
// drawn with the pen at (x, y) covers x + offset .. x + offset + width - 1
// and y .. y + kPaintFontHeight - 1.

static const int kPaintFontHeight = 16;

struct Glyph {
	int					code;
	int					width;		// length of each row string
	int					offset;		// x offset from the pen position
	int					advance;	// pen advance (QuickDraw's CharWidth)
	const char* const*	rows;		// kPaintFontHeight rows, '#' is black
};

// NULL if PaintFont has no such character.
const Glyph*	PaintFontGlyph(int code);


// Character codes, from MacPaint.p (DrawTool, SetToolCursor, InvLnSize).
enum {
	kGlyphCheck				= 65,
	kGlyphFirstTool			= 69,	// 20 tool icons, two per palette row
	kGlyphLineCursor1		= 89,	// line tool crosshairs for sizes 1..8
	kGlyphLineCursor2		= 90,
	kGlyphLineCursor4		= 91,
	kGlyphLineCursor8		= 92,
	kGlyphFillMask			= 93,
	kGlyphSpray				= 111,	// spray can cursor, also its nozzle mask
	kGlyphPencilMask		= 116,
	kGlyphEraserBox			= 119,
	kGlyphAllOnes			= 120,
	kGlyphFirstBrush		= 120	// 32 brush shapes, 120 + theBrush
};

static const int kBrushCount = 32;
static const int kDefaultBrush = 7;		// "small round brush"


#endif	// PAINT_FONT_H
